func getAuthUser(ctx context.Context) *auth.UserContext {
	userCtx, ok := auth.UserFromContext(ctx)
	if !ok || userCtx == nil {
		if u, ok2 := auth.FromContext(ctx); ok2 && u != nil {
			return u
		}
		return nil
	}
	return userCtx
}
